guide_queries:
PROFILE MATCH (v:article)
WHERE v.article.body CONTAINS "数据库"
RETURN id(v) AS id LIMIT 5;

PROFILE LOOKUP ON article
WHERE article.body CONTAINS "Graph"
YIELD id(vertex) AS id;

LOOKUP ON article
WHERE article.body CONTAINS "graph"
YIELD id(vertex) AS id;

